/* Explanations are derived from computed chart data, never from a language model. */
(function(root){'use strict';
const H=typeof module==='object'?require('./engine.js'):root.Horar;
const houseTopics=['','сам задающий вопрос','личные деньги и вещи','короткие поездки и начальное обучение','дом и недвижимость','дети и творчество','повседневный труд','партнёр и отношения','ресурсы партнёра','дальние поездки и высшее образование','работа и должность','друзья и сообщество','скрытые обстоятельства'];
const aspectMeanings={0:'Соединение объединяет показатели в одной области карты. Его трактовка зависит от участвующих планет и их состояния.',60:'Секстиль традиционно связывают с возможностью взаимодействия, для которой могут потребоваться действия.',90:'Квадрат традиционно описывает взаимодействие через трудности, несогласованность или усилие.',120:'Трин традиционно связывают с более лёгким взаимодействием и меньшим сопротивлением.',180:'Оппозицию традиционно связывают с противостоянием, расхождением интересов или необходимостью компромисса.'};
const glossary=[
 ['Хорарная карта','Карта неба на выбранный момент вопроса. Это не натальная карта: дата рождения здесь не используется.'],
 ['Момент вопроса','Приложение использует время, которое вы ввели. Кнопка «Сейчас» — удобный способ заполнения, а не определение единственно верного момента. В разных школах момент постановки или понимания вопроса выбирают по-разному.'],
 ['UTC','Единая временная шкала. Из местного времени вычитается указанное смещение: 17:00 при UTC+3 соответствует 14:00 UTC. Для исторических дат и перевода часов проверяйте смещение.'],
 ['ASC / асцендент','Точка пересечения эклиптики с восточной частью горизонта. Знак куспида I дома определяет основного управителя задающего вопрос.'],
 ['MC / середина неба','Верхнее пересечение эклиптики с меридианом. В системе Региомонтана это куспид X дома; в других выбранных системах совпадение не обязательно.'],
 ['Дом и куспид','Дом — сектор карты, которому в традиции соответствует область жизни. Куспид — начало сектора. Номер дома планеты определяется её долготой относительно этих границ.'],
 ['Сигнификатор','Планета, выбранная для представления стороны вопроса. Здесь выбор делается по традиционному управителю знака на куспиде соответствующего дома.'],
 ['Управитель знака','В приложении: Марс — Овен и Скорпион; Венера — Телец и Весы; Меркурий — Близнецы и Дева; Луна — Рак; Солнце — Лев; Юпитер — Стрелец и Рыбы; Сатурн — Козерог и Водолей.'],
 ['Аспект','Угловое расстояние между двумя планетами. Здесь проверяются соединение, секстиль, квадрат, трин и оппозиция — 0°, 60°, 90°, 120°, 180°.'],
 ['Орбис','Отклонение от точного угла аспекта. Например, при расстоянии 88° орбис квадрата равен 2°. Это угол, а не число дней до события.'],
 ['Сходящийся аспект','Орбис уменьшается по текущему движению. Разворот планеты, переход в другой знак и другие условия могут помешать точному аспекту; расширенный разбор проверяет смену знака и станции до точного контакта.'],
 ['Расходящийся аспект','Орбис увеличивается по текущему движению. Традиционно его связывают с предысторией, но приложение не устанавливает, какое именно событие произошло.'],
 ['Обитель и экзальтация','Два вида традиционных достоинств. Обитель связывают с привычными для планеты условиями, экзальтацию — с усилением её положения. Это не оценка характера или нравственности человека.'],
 ['Изгнание и падение','Традиционные положения напротив обители или экзальтации. Их связывают с ограничениями проявления планеты. Они не означают, что человек плох или событие обязательно провалится.'],
 ['Рецепция','Планета находится в знаке достоинства другой планеты. Принимающая планета названа первой. Расширенный разбор учитывает обитель, экзальтацию, триплицитет, терм, фас и негативную рецепцию. Рецепция не доказывает любовь, согласие или намерение реального человека.'],
 ['Ретроградность ℞','Видимое обратное движение по геоцентрической долготе, не физическое движение планеты назад по орбите. В символическом разборе может связываться с пересмотром или возвратом.'],
 ['Казими, сожжение, под лучами','Здесь используются расстояния от Солнца: меньше 17′ — казими; от 17′ до 8°30′ — сожжение; от 8°30′ до 17° — под лучами. Пороги являются настройкой данной методики, а не физическими границами воздействия.'],
 ['Луна без курса','В этой версии: до смены знака Луна не образует точного мажорного аспекта с другими классическими планетами. В школах встречаются другие определения. Это не автоматический отрицательный ответ.'],
 ['Ранний и поздний ASC','Первые 3° и последние 3° знака выделены как традиционные предостережения. Приложение не запрещает расчёт такой карты и не считает её автоматически ошибочной.'],
 ['Отсутствие показателя','Отсутствие аспекта или достоинства в ограниченном наборе правил не равно отсутствию возможностей в жизни. Итог требует контекста и правил, которые могут не входить в автоматический разбор.']
];
function position(l){return `${(l%30).toFixed(2)}° ${H.signs[Math.floor(l/30)]}`;}
function planetMeaning(p){const parts=[];if(p.dignity.includes('Обитель'))parts.push('В традиционной системе планета находится в собственном знаке; это трактуют как более самостоятельное положение.');if(p.dignity.includes('Экзальтация'))parts.push('Экзальтация символически усиливает положение планеты; это не гарантирует реализации вопроса.');if(p.dignity.includes('Изгнание'))parts.push('Изгнание в этой системе связывают с ограничениями или зависимостью от условий.');if(p.dignity.includes('Падение'))parts.push('Падение символически описывает затруднённое проявление качеств планеты.');if(!parts.length)parts.push('Обитель, экзальтация, изгнание и падение не найдены. Остальные достоинства здесь не оцениваются, поэтому называть планету полностью слабой нельзя.');parts.push(p.retro?'Ретроградность добавляет тему пересмотра или возврата в символической трактовке.':'Прямое движение само по себе не указывает на успех.');return parts.join(' ');}
function advanced(c){const a=c.analysis,q=c.planets[c.querent],s=c.planets[c.subject],route=a.route;
const step=(title,fact,meaning,limit)=>({title,fact,meaning,limit});
return [
step('1. Вопрос, участники и дома',`Вопрос: «${c.input.question}». ${a.context.label}. Режим: ${c.input.topicMode==='auto'?'по тексту':'ручной'}. Участник: ${a.actorHouse} дом (${q.name}); цель: ${c.input.target} дом (${s.name}).`,a.context.reason+(a.actorHouse!==1?' Использован производный дом: отсчёт темы от дома названного человека.':''),'Распознавание основано на явных словах и поддерживаемых ролях. Сложный, отрицательный или составной вопрос требует проверки выбранного дома.'),
step('2. Состояние участника',`${q.name}: ${position(q.lon)}, дом ${q.house}. ${a.states[q.i].summary}`,`Сумма эссенциальных достоинств: ${a.states[q.i].score}. Это условные веса обители, экзальтации, триплицитета, терма и фаса с учётом изгнания и падения. Угловое положение, движение и близость к Солнцу рассматриваются отдельно.`,'Баллы достоинств не являются процентом вероятности события и не складываются в достоверность прогноза.'),
step('3. Состояние цели',`${s.name}: ${position(s.lon)}, дом ${s.house}. ${a.states[s.i].summary}`,q.i===s.i?'Один управитель для двух ролей. Не считаем его дважды как независимые свидетельства.':'Положение показывает символическую способность стороны действовать. Ретроградность может обозначать пересмотр; в вопросе о возвращении её смысл отличается от вопроса о новом начинании.','Это описание правил карты, а не установленных намерений или возможностей реального человека.'),
step('4. Будущая связь и изменение условий',a.direct.event?`${a.direct.event.name}: ${a.direct.event.utc}. ${a.direct.blocked.map(e=>H.names[e.i]+': '+(e.type==='ingress'?'смена знака':'станция')+' '+e.utc).join('; ')||'Смены знака и станции до контакта не найдены.'}`:'Отдельной прямой связи нет в окне поиска.',route?`${route.type==='direct'?'Прямой контакт':route.type==='translation'?'Передача света через '+H.names[route.via]:'Собирание света у '+H.names[route.via]}. ${aspectMeanings[route.event.angle]}`:`Поиск выполнен на ${a.days} дней. Контакт после смены знака или станции отмечается отдельно и не выдаётся за осуществление в прежних условиях.`,a.interference?`Возможное вмешательство до контакта: ${H.names[a.interference.i]} — ${H.names[a.interference.j]}, ${a.interference.name}, ${a.interference.utc}. Само по себе это не доказанный запрет.`:'Точная дата аспекта — астрономический момент. Она не равна сроку жизненного события.'),
step('5. Рецепции и посредники',c.receptions.length?c.receptions.join(' '):'Управитель один; взаимная рецепция неприменима.',`Проверены обитель, экзальтация, триплицитет, египетский терм, фас, изгнание и падение. Найдено путей через посредника: ${a.paths.length}. Принимающая планета всегда названа первой.`,'Негативная рецепция не доказывает неприязнь. Передача и собирание — ограниченные вычислительные правила, которые требуют чтения вместе с состоянием сторон.'),
step('6. Луна и ход вопроса',`Луна: ${position(c.planets[1].lon)}. ${c.lunar.void?'Без курса до выхода из знака.':'До выхода из знака аспектов: '+c.lunar.events.length+'.'} Смена знака: ${c.lunar.ingress}. Последний завершённый аспект: ${a.lunarLast?a.lunarLast.name+' с '+H.names[a.lunarLast.i===1?a.lunarLast.j:a.lunarLast.i]+' '+a.lunarLast.utc:'не найден за предыдущие 4 дня'}.`,c.lunar.events.slice(0,4).map(e=>`${e.name} с ${H.names[e.i]}: ${e.utc}.`).join(' ')||'Не найдено точных мажорных аспектов с классическими планетами до смены знака.','Если Луна уже является сигнификатором, её связь не становится вторым независимым доказательством. Определение Луны без курса в разных школах отличается.'),
step('7. Соображения перед суждением',a.checks.map(x=>`${x.active?'Предостережение':'Не отмечено'}: ${x.label}.`).join(' '),`Активных предостережений: ${a.checks.filter(x=>x.active).length} из 7. Четыре и более переключают итог в осторожный режим. Это открытое правило приложения, а не универсальный исторический запрет.`,'Проверки не независимы: Сатурн в VII входит также в поражение VII. Количество не является статистической оценкой радикальности.'),
step('8. Итог и его основания',c.verdict+'. '+c.explanation,a.evidence.map(x=>`${x.direction==='support'?'Поддержка':x.direction==='obstacle'?'Препятствие':'Контекст'}: ${x.text}`).join(' '),a.limits)
];}
function explain(c){if(c.analysis)return advanced(c);const q=c.planets[c.querent],s=c.planets[c.subject],primary=c.primary;
const steps=[
 {title:'1. Почему выбраны именно эти планеты',fact:`I дом начинается в знаке ${H.signs[Math.floor(c.cusps[0]/30)]}, его управитель — ${q.name}. Предмет вопроса: ${houseTopics[c.input.target]}, ${c.input.target} дом; его куспид — ${position(c.cusps[c.input.target-1])}, управитель — ${s.name}.`,meaning:c.querent===c.subject?'У обеих ролей один управитель. Программа не подменяет его произвольной другой планетой.':'Эти управители обозначают две роли в карте и служат основой сравнения.',limit:'Если предмет вопроса относится к другому дому, изменится и разбор. Сам текст вопроса не выбирает дом автоматически.'},
 {title:'2. Ваш показатель',fact:`${q.name}: ${position(q.lon)}, дом ${q.house}; ${q.dignity.join(', ')}; скорость ${q.speed.toFixed(4)}°/сутки.`,meaning:planetMeaning(q),limit:'Состояние сигнификатора не является психологическим диагнозом и не определяет ваши реальные возможности.'},
 {title:'3. Показатель предмета вопроса',fact:`${s.name}: ${position(s.lon)}, дом ${s.house}; ${s.dignity.join(', ')}; скорость ${s.speed.toFixed(4)}°/сутки.`,meaning:planetMeaning(s),limit:'Этот показатель не позволяет достоверно прочитать мысли или намерения другого человека.'},
 {title:'4. Есть ли связь между управителями',fact:c.querent===c.subject?'Один управитель для двух ролей: отдельная пара планет отсутствует.':primary?`${primary.name} (${primary.angle}°), орбис ${primary.orb.toFixed(4)}°; ${H.phaseLabel(primary.phase).toLowerCase()}.`:'Мажорного аспекта в принятом орбисе между управителями нет.',meaning:primary?aspectMeanings[primary.angle]:'Нельзя свести отсутствие отдельного аспекта к ответу «нет». Другие способы связи в этой версии не анализируются.',limit:'Даже сходящийся трин не является обещанием события, а квадрат не является автоматическим отказом. Срок события из орбиса здесь не вычисляется.'},
 {title:'5. Что добавляют рецепции',fact:c.querent===c.subject?'Проверка взаимной рецепции неприменима: управитель один.':c.receptions.length?c.receptions.join(' '):'Рецепций по обители или экзальтации между управителями не обнаружено.',meaning:'Рецепции описывают символическое отношение планет через достоинства знаков. Их оценивают вместе с аспектами и состоянием управителей.',limit:'Здесь не проверяются рецепции по триплицитету, терму и фасу. Отсутствие показателя не означает отсутствия чувств.'},
 {title:'6. Роль Луны',fact:`Луна: ${position(c.planets[1].lon)}, дом ${c.planets[1].house}.`,meaning:c.querent===1||c.subject===1?'Луна уже является одним из основных управителей. Её показатели не нужно считать вторым независимым подтверждением.':'Луна рассматривается как дополнительный показатель хода вопроса. Следующие точные аспекты приведены отдельным списком.',limit:'Время точного аспекта — астрономический момент, а не предсказанная дата встречи, выплаты или другого события.'},
 {title:'7. Где нужна осторожность',fact:c.notices.length?c.notices.join(' '):'Ранний/поздний ASC, Сатурн в VII и близость выбранных управителей к Солнцу не дали предупреждений по принятым порогам.',meaning:'Это контрольные замечания внутри традиционной методики, а не запрет пользоваться картой.',limit:'Отсутствие предупреждений не доказывает надёжность прогноза.'},
 {title:'8. Как читать итог',fact:c.verdict+'. '+c.explanation,meaning:'Сопоставьте основания выше, а затем сохраните вопрос. В журнале запишите фактический исход своими словами, чтобы не подгонять его под трактовку.',limit:'Автоматическое суждение ограничено показанными правилами. Оно не учитывает передачу и собирание света, запрет, рефранацию, производные дома и все условия совершенствования аспекта.'}
];return steps;}
const api={explain,glossary,planetMeaning,aspectMeanings,houseTopics};if(typeof module==='object')module.exports=api;else root.HorarReading=api;
})(typeof globalThis!=='undefined'?globalThis:this);
